import "server-only";
import { prisma } from "@formbricks/database";
import { logger } from "@formbricks/logger";
import {
  problemInternalError,
  problemUnauthorized,
  successResponse,
} from "@/app/api/v3/lib/response";
import type { TV3Authentication } from "@/app/api/v3/lib/types";
import { serializeV3AccountDataExport } from "../serializers";

type TParams = {
  authentication: TV3Authentication;
  requestId: string;
  instance?: string;
};

export async function exportV3AccountData({ authentication, requestId, instance }: TParams): Promise<Response> {
  const userId = authentication && "user" in authentication ? authentication.user?.id : undefined;
  if (!userId) {
    return problemUnauthorized(requestId, "Session required", instance);
  }

  try {
    // One query for the user and their memberships. Bounded by the number of organizations the user
    // belongs to, and scoped to the session user's own id.
    const user = await prisma.user.findUnique({
      where: { id: userId },
      select: {
        name: true,
        email: true,
        locale: true,
        notificationSettings: true,
        memberships: {
          where: { accepted: true },
          select: { role: true, organization: { select: { name: true } } },
          orderBy: { organization: { name: "asc" } },
        },
      },
    });

    if (!user) {
      return problemUnauthorized(requestId, "Session required", instance);
    }

    return successResponse(serializeV3AccountDataExport(user), { requestId });
  } catch (error) {
    logger.error({ error, requestId }, "Failed to export account data");
    return problemInternalError(requestId, "An unexpected error occurred.", instance);
  }
}
EOF
